// Extraire les données du commentaire depuis le payload Meta
const body = $input.first().json.body;

const entries = body.entry || [];
const results = [];

for (const entry of entries) {
  for (const change of entry.changes || []) {
    if (change.field === 'comments') {
      results.push({
        comment_id: change.value.id,
        text: change.value.text,
        username: change.value.from?.username || 'inconnu',
        user_id: change.value.from?.id || '',
        media_id: change.value.media?.id || '',
        timestamp: new Date().toISOString()
      });
    }
  }
}

if (results.length === 0) {
  results.push({ skip: true, reason: 'Pas un commentaire' });
}

return results.map(r => ({ json: r }));

// Liste de mots-clés à bloquer
const BLACKLIST = [
  'spam', 'fake', 'arnaque', 'scam', 'clickbait',
  'follow me', 'check my', 'dm me', 'link in bio'
];

const text = $input.first().json.text.toLowerCase();
const isSpam = BLACKLIST.some(kw => text.includes(kw));

return [{
  json: {
    ...$input.first().json,
    is_spam: isSpam
  }
}];

