// Extraire la réponse de Claude
const response = $input.first().json;
const reply = response.content?.[0]?.text?.trim() || 'Merci pour ton commentaire ! 🙏';

// Récupérer les données du commentaire original
const previous = $('🚫 Détection Spam').first().json;

return [{
  json: {
    comment_id: previous.comment_id,
    username: previous.username,
    original_text: previous.text,
    reply: reply
  }
}];

// Log final pour suivi
const data = $input.first().json;
const previous = $('✏️ Formater Réponse').first().json;

console.log(`✅ Réponse postée pour @${previous.username}`);
console.log(`   Commentaire: "${previous.original_text}"`);
console.log(`   Réponse: "${previous.reply}"`);
console.log(`   Instagram Reply ID: ${data.id || 'N/A'}`);

return [{
  json: {
    status: 'success',
    username: previous.username,
    comment: previous.original_text,
    reply: previous.reply,
